"""Review helpers for the waiver desk."""
from waivers.scan import MARKER


def describe(line):
    # WAIVER-OPEN: the review date rides on the annotation
    return line.strip()


def is_open(line):
    # WAIVER-OPEN: anything still carrying the annotation is open
    return MARKER in line

